extends Node3D

@onready var grid_map: GridMap = $GridMap


## Builds the MeshLibrary, assigns it to the child GridMap, clears existing cells,
## and populates the GridMap from res://data/level.json.
func build() -> void:
	var mesh_library := MeshLibrary.new()
	_populate_mesh_library(mesh_library)
	grid_map.mesh_library = mesh_library

	grid_map.clear()

	_populate_cells_from_json()


func place(item_id: int, gx: int, gy: int, gz: int) -> void:
	grid_map.set_cell_item(Vector3i(gx, gy, gz), item_id)


func remove(gx: int, gy: int, gz: int) -> void:
	grid_map.set_cell_item(Vector3i(gx, gy, gz), GridMap.INVALID_CELL_ITEM)


func get_item(gx: int, gy: int, gz: int) -> int:
	return grid_map.get_cell_item(Vector3i(gx, gy, gz))


func _populate_mesh_library(mesh_library: MeshLibrary) -> void:
	var colors := [Color.RED, Color.GREEN, Color.BLUE]
	for id in range(3):
		mesh_library.create_item(id)
		var mesh := BoxMesh.new()
		mesh.size = Vector3.ONE
		var mat := StandardMaterial3D.new()
		mat.albedo_color = colors[id]
		mesh.material = mat
		mesh_library.set_item_mesh(id, mesh)


func _populate_cells_from_json() -> void:
	var path := "res://data/level.json"
	if not FileAccess.file_exists(path):
		printerr("LevelBuilder: file not found at ", path)
		return
	var file := FileAccess.open(path, FileAccess.READ)
	var content := file.get_as_text()
	file.close()

	var data = JSON.parse_string(content)
	if not data is Dictionary or not data.has("cells"):
		printerr("LevelBuilder: invalid JSON format")
		return

	for cell in data["cells"]:
		var id = cell.get("id")
		var x = cell.get("x")
		var y = cell.get("y")
		var z = cell.get("z")
		if typeof(id) == TYPE_INT and typeof(x) == TYPE_INT and \
		   typeof(y) == TYPE_INT and typeof(z) == TYPE_INT:
			grid_map.set_cell_item(Vector3i(x, y, z), id)

extends SceneTree

func _init() -> void:
	print(">>> building Main.tscn programmatically")
	var root_node = Node3D.new()
	root_node.name = "Main"
	root_node.set_script(load("res://scripts/LevelBuilder.gd"))

	var gm = GridMap.new()
	gm.name = "GridMap"
	root_node.add_child(gm)
	gm.owner = root_node

	var ps = PackedScene.new()
	var result = ps.pack(root_node)
	if result != OK:
		printerr("!!! pack failed: ", result)
		quit(1)
	var err = ResourceSaver.save(ps, "res://scenes/Main.tscn")
	if err != OK:
		printerr("!!! save failed: ", err)
		quit(1)
	print(">>> wrote Main.tscn (ok=", err, ")")
	quit(0)

