## Builds the MeshLibrary, assigns it to the child GridMap, clears existing cells,
## and populates the GridMap from res://data/level.json.
func build() -> void:
	var gm := _get_grid_map()
	if not gm:
		return

	var mesh_library := MeshLibrary.new()
	_populate_mesh_library(mesh_library)
	gm.mesh_library = mesh_library

	gm.clear()

	_populate_cells_from_json(gm)


func place(item_id: int, gx: int, gy: int, gz: int) -> void:
	var gm := _get_grid_map()
	if gm:
		gm.set_cell_item(Vector3i(gx, gy, gz), item_id)


func remove(gx: int, gy: int, gz: int) -> void:
	var gm := _get_grid_map()
	if gm:
		gm.set_cell_item(Vector3i(gx, gy, gz), GridMap.INVALID_CELL_ITEM)


func get_item(gx: int, gy: int, gz: int) -> int:
	var gm := _get_grid_map()
	if not gm:
		return -1
	return gm.get_cell_item(Vector3i(gx, gy, gz))


## Resolves the child GridMap node. Guaranteed reachable via node path "GridMap"
## when the node is in the scene tree.
func _get_grid_map() -> GridMap:
	var node := get_node_or_null("GridMap")
	if node is GridMap:
		return node
	printerr("LevelBuilder: child GridMap not found")
	return null


